insert into public.merch_products(id,slug,name,sku,description,category,price_centavos,status,images,content) values(1,'whats-it-gonna-be-tee','What''s It Gonna Be Tee','UPD-1','Built for spontaneous road trips, weekend hikes, and everything in between. The What’s It Gonna Be Tee pairs everyday comfort with an adventure-inspired graphic designed to represent the places worth getting lost in. Whether it is beaches, rivers, or waterfalls, this tee is your reminder to keep chasing the next horizon.','Tees',99900,'publish','[{"src":"/merch/images/tee1-display.png","alt":"What''s It Gonna Be Tee"},{"src":"/merch/images/tee1-front.png","alt":"What''s It Gonna Be Tee"},{"src":"/merch/images/tee1-back.png","alt":"What''s It Gonna Be Tee"},{"src":"/merch/images/tee1-detail.png","alt":"What''s It Gonna Be Tee"}]'::jsonb,'{"color":"Navy","descriptor":"Front & Back Design","shortDescription":"A premium heavyweight cotton tee with a subtle front chest emblem and a bold statement back graphic.","about":"Built for spontaneous road trips, weekend hikes, and everything in between. The What’s It Gonna Be Tee pairs everyday comfort with an adventure-inspired graphic designed to represent the places worth getting lost in. Whether it is beaches, rivers, or waterfalls, this tee is your reminder to keep chasing the next horizon.","badge":"NEW ARRIVAL","details":{"material":"100% Premium Cotton","fit":"Relaxed Fit","weight":"Heavyweight","care":"Machine wash cold / Hang dry"},"highlights":["Premium cotton construction","Front and back screen-printed graphic","Relaxed everyday fit","Soft, breathable and built to last","Designed for outdoor adventures"],"sizeGuide":[{"size":"S","chest":"20\"","length":"27\"","shoulder":"18\""},{"size":"M","chest":"21\"","length":"28\"","shoulder":"19\""},{"size":"L","chest":"23\"","length":"29\"","shoulder":"20\""},{"size":"XL","chest":"25\"","length":"30\"","shoulder":"21\""},{"size":"XXL","chest":"27\"","length":"31\"","shoulder":"22\""}],"related":["wander-pullover-hoodie","summit-trail-cap","explorer-canvas-tote"]}'::jsonb);
