insert into public.merch_products(id,slug,name,sku,description,category,price_centavos,status,images,content) values(2,'wander-pullover-hoodie','Wander Pullover Hoodie','UPD-2','When the trail turns cold and the sun dips behind the ridge, the Wander Pullover Hoodie keeps you moving. Brushed fleece on the inside, a clean mountain-line graphic on the back, and a relaxed silhouette that layers over anything. Made for early call times, campfire nights, and the long drive home.','Hoodies',189900,'publish','[{"src":"/merch/images/hoodie-display.png","alt":"Wander Pullover Hoodie"},{"src":"/merch/images/hoodie-back.png","alt":"Wander Pullover Hoodie"}]'::jsonb,'{"color":"Sand","descriptor":"Heavyweight Fleece","shortDescription":"A cozy heavyweight fleece pullover finished with a minimalist mountain range printed across the back.","about":"When the trail turns cold and the sun dips behind the ridge, the Wander Pullover Hoodie keeps you moving. Brushed fleece on the inside, a clean mountain-line graphic on the back, and a relaxed silhouette that layers over anything. Made for early call times, campfire nights, and the long drive home.","badge":"BESTSELLER","details":{"material":"80% Cotton / 20% Polyester","fit":"Regular Fit","weight":"Heavyweight Fleece","care":"Machine wash cold / Tumble dry low"},"highlights":["Brushed heavyweight fleece interior","Minimalist mountain-range back print","Ribbed cuffs and hem for warmth","Kangaroo pocket","Relaxed layering fit"],"sizeGuide":[{"size":"S","chest":"20\"","length":"27\"","shoulder":"18\""},{"size":"M","chest":"21\"","length":"28\"","shoulder":"19\""},{"size":"L","chest":"23\"","length":"29\"","shoulder":"20\""},{"size":"XL","chest":"25\"","length":"30\"","shoulder":"21\""},{"size":"XXL","chest":"27\"","length":"31\"","shoulder":"22\""}],"related":["whats-it-gonna-be-tee","summit-trail-cap","explorer-canvas-tote"]}'::jsonb);
