insert into public.merch_products(id,slug,name,sku,description,category,price_centavos,status,images,content) values(3,'summit-trail-cap','Summit Trail Cap','UPD-3','Shade for the summit and everything before it. The Summit Trail Cap keeps the sun out of your eyes with a structured crown, a curved brim, and a tonal embroidered emblem that quietly says you have been places. One adjustable strap, endless trails.','Headwear',69900,'publish','[{"src":"/merch/images/cap-display.png","alt":"Summit Trail Cap"},{"src":"/merch/images/cap-side.png","alt":"Summit Trail Cap"}]'::jsonb,'{"color":"Navy","descriptor":"Embroidered Logo","shortDescription":"A structured six-panel cap with a clean embroidered palm emblem and an adjustable strap for any head size.","about":"Shade for the summit and everything before it. The Summit Trail Cap keeps the sun out of your eyes with a structured crown, a curved brim, and a tonal embroidered emblem that quietly says you have been places. One adjustable strap, endless trails.","details":{"material":"Cotton Twill","fit":"Adjustable Strap","weight":"Structured Crown","care":"Spot clean only"},"highlights":["Structured six-panel crown","Tonal embroidered palm emblem","Curved brim","Adjustable back strap","One size fits most"],"related":["whats-it-gonna-be-tee","wander-pullover-hoodie","explorer-canvas-tote"]}'::jsonb);
