insert into public.merch_products(id,slug,name,sku,description,category,price_centavos,status,images,content) values(4,'explorer-canvas-tote','Explorer Canvas Tote','UPD-4','Made from heavy natural canvas that only gets better with wear, the Explorer Canvas Tote carries your day trips with room to spare. Reinforced handles, a roomy main compartment, and a printed sun-and-mountain badge on the front. Reusable, rugged, and ready for whatever you throw in it.','Bags',54900,'publish','[{"src":"/merch/images/tote-display.png","alt":"Explorer Canvas Tote"}]'::jsonb,'{"color":"Natural","descriptor":"Heavy Canvas","shortDescription":"A durable heavy-canvas tote with a printed adventure badge — built for market runs and shoreline hauls.","about":"Made from heavy natural canvas that only gets better with wear, the Explorer Canvas Tote carries your day trips with room to spare. Reinforced handles, a roomy main compartment, and a printed sun-and-mountain badge on the front. Reusable, rugged, and ready for whatever you throw in it.","badge":"ECO","details":{"material":"100% Heavy Cotton Canvas","fit":"Oversized Carry-All","weight":"16 oz Canvas","care":"Hand wash / Air dry"},"highlights":["Heavy 16 oz cotton canvas","Reinforced carry handles","Printed sun-and-mountain badge","Roomy main compartment","Reusable and eco-friendly"],"related":["whats-it-gonna-be-tee","wander-pullover-hoodie","summit-trail-cap"]}'::jsonb);
